{
  "packet_id": "H6-T01-1",
  "claim_id": "C056",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C056.component",
    "value": "The persistence rule does not provide causal identification.",
    "scope": "The provisional investigation rule, even when its stated conditions are met.",
    "provenance": {
      "refs": [
        {
          "source_id": "P011",
          "role": "CONTEXT"
        },
        {
          "source_id": "P025",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P025 explicitly states this limitation; P011 identifies the provisional persistence rule."
    }
  },
  "signal_basis": {
    "component_id": "C056.signal_basis",
    "value": "A candidate bottleneck recurs on multiple booking days in each investigation week, with the same stage accounting for the greatest documented delay burden in both weeks.",
    "scope": "The two-week prospective investigation, using consistent event definitions and comparable equipment and crew groups, with sufficient bookings and missing records that cannot reverse the ranking.",
    "provenance": {
      "refs": [
        {
          "source_id": "P011",
          "role": "SUPPORT"
        },
        {
          "source_id": "P006",
          "role": "SUPPORT"
        },
        {
          "source_id": "P010",
          "role": "SUPPORT"
        },
        {
          "source_id": "P014",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P011 supplies the temporal pattern and delay ranking; P006, P010 and P014 supply the measurement, comparability and evidence-adequacy bounds."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C056.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is supported directly within its bounds, so no conditional empirical relation is applicable."
    }
  },
  "rationale": "Meeting the persistence rule establishes recurrence and a documented delay ranking. Those observations do not isolate causal effects or distinguish the stage's causal contribution from other influences. The mapping expressly acknowledges potential influences on observed patterns in P024 and limits the rule to practical selection in P025. The frozen claim accurately states that inferential limit.",
  "uncertainty": "No material uncertainty about this limited claim. Assuming the signal occurs does not resolve causal attribution.",
  "anomalies": []
}
